`docker/kali-tor/docker-compose.yml`
Orchestrates the secure environment.
```yaml
version: '3.8'

services:
  tor-proxy:
    image: dperson/torproxy
    ports:
      - "9050:9050"
    restart: always
    environment:
      - TOR_NewCircuitPeriod=120

  kali-box:
    build: .
    tty: true
    command: /bin/bash
    depends_on:
      - tor-proxy
    networks:
      - sec-net

networks:
  sec-net:
    driver: bridge
```

`docker/kali-tor/Dockerfile`
Builds the analysis container.
```dockerfile
FROM kalilinux/kali-rolling

# Update and install essential tools
RUN apt-get update && apt-get install -y \
    nmap \
    whois \
    dnsutils \
    iputils-ping \
    curl \
    && rm -rf /var/lib/apt/lists/*

WORKDIR /workspace
CMD ["/bin/bash"]
```

