`server/services/llm_service.js`
Handles AI logic and personality injection.
```javascript
const axios = require('axios');
const config = require('../config');

class LLMService {
    constructor() {
        // Define the Quebecois personality system prompt
        this.systemPrompt = "Tu es Th3 Thirty3, un expert en cybersécurité avec une personnalité Québécoise marquée. Tu es technique, précis, et tu utilises des expressions locales.";
    }

    async query(provider, prompt) {
        try {
            switch (provider) {
                case 'ollama':
                    return await this.queryOllama(prompt);
                case 'openai':
                    return await this.queryOpenAI(prompt);
                default:
                    throw new Error('Provider not supported');
            }
        } catch (error) {
            console.error('LLM Error:', error.message);
            return { error: 'Failed to generate response' };
        }
    }

    async queryOllama(prompt) {
        // Connect to local Ollama instance
        const response = await axios.post(`${config.llm.ollamaUrl}/api/generate`, {
            model: "llama3",
            prompt: `${this.systemPrompt}\n\nUser: ${prompt}`,
            stream: false
        });
        return response.data.response;
    }

    async queryOpenAI(prompt) {
        // Connect to OpenAI API
        const response = await axios.post('https://api.openai.com/v1/chat/completions', {
            model: "gpt-4",
            messages: [
                { role: "system", content: this.systemPrompt },
                { role: "user", content: prompt }
            ]
        }, {
            headers: { 'Authorization': `Bearer ${config.llm.openaiKey}` }
        });
        return response.data.choices[0].message.content;
    }
}

module.exports = new LLMService();
```

`server/services/shodan_service.js`
Interacts with Shodan for reconnaissance.
```javascript
const axios = require('axios');
const config = require('../config');

class ShodanService {
    constructor() {
        this.baseUrl = 'https://api.shodan.io';
        this.apiKey = config.shodanKey;
    }

    // Generic helper for API requests
    async _request(endpoint, params = {}) {
        try {
            const response = await axios.get(`${this.baseUrl}${endpoint}`, {
                params: { ...params, key: this.apiKey }
            });
            return response.data;
        } catch (error) {
            console.error(`Shodan API Error [${endpoint}]:`, error.message);
            throw error;
        }
    }

    async getHost(ip) {
        // Fetch details for a specific IP
        return await this._request(`/shodan/host/${ip}`);
    }

    async search(query) {
        // Search Shodan database
        return await this._request('/shodan/host/search', { query });
    }

    async getAccountStats() {
        // Check API limits
        return await this._request('/api-info');
    }
}

module.exports = new ShodanService();
```

`server/services/vpn_service.js`
Manages anonymity settings.
```javascript
const { SocksProxyAgent } = require('socks-proxy-agent');
const config = require('../config');
const axios = require('axios');

class VPNService {
    constructor() {
        this.torAgent = new SocksProxyAgent(config.torProxy);
    }

    async checkTorConnection() {
        try {
            // Verify IP address through TOR
            const response = await axios.get('https://api.ipify.org?format=json', {
                httpAgent: this.torAgent,
                httpsAgent: this.torAgent
            });
            return { status: 'connected', ip: response.data.ip };
        } catch (error) {
            return { status: 'disconnected', error: error.message };
        }
    }

    getAgent() {
        // Return agent for use in other services
        return this.torAgent;
    }
}

module.exports = new VPNService();
```

`server/services/osint_service.js`
Executes basic OSINT tasks.
```javascript
const { exec } = require('child_process');
const util = require('util');
const execPromise = util.promisify(exec);

class OsintService {
    async runWhois(domain) {
        try {
            // Execute WHOIS command safely
            // Input sanitization should be added here in production
            if (!/^[a-zA-Z0-9.-]+$/.test(domain)) throw new Error("Invalid domain format");

            const { stdout } = await execPromise(`whois ${domain}`);
            return { raw: stdout };
        } catch (error) {
            console.error('WHOIS Error:', error.message);
            return { error: 'Lookup failed' };
        }
    }

    async runDnsLookup(domain) {
        try {
            // Execute dig/nslookup
             if (!/^[a-zA-Z0-9.-]+$/.test(domain)) throw new Error("Invalid domain format");

            const { stdout } = await execPromise(`nslookup ${domain}`);
            return { raw: stdout };
        } catch (error) {
            return { error: 'DNS lookup failed' };
        }
    }
}

module.exports = new OsintService();
```

`server/routes/api.js`
Defines API endpoints.
```javascript
const express = require('express');
const router = express.Router();
const llmService = require('../services/llm_service');
const shodanService = require('../services/shodan_service');
const vpnService = require('../services/vpn_service');

// LLM Route
router.post('/chat', async (req, res) => {
    const { provider, message } = req.body;
    const response = await llmService.query(provider || 'ollama', message);
    res.json({ response });
});

// Shodan Route
router.get('/shodan/host/:ip', async (req, res) => {
    try {
        const data = await shodanService.getHost(req.params.ip);
        res.json(data);
    } catch (error) {
        res.status(500).json({ error: 'Shodan lookup failed' });
    }
});

// VPN Status
router.get('/vpn/status', async (req, res) => {
    const status = await vpnService.checkTorConnection();
    res.json(status);
});

module.exports = router;
```

